import{_ as r,c as a,o as t,a2 as n}from"./chunks/framework.PGES7OoM.js";const h=JSON.parse('{"title":"Curvy for wallets & Web3 product builders","description":"","frontmatter":{"rawMarkdown":"# Curvy for wallets & Web3 product builders\\n\\nCurvy enables wallets and Web3 applications to integrate privacy flows directly into their product with **zero upfront cost** and minimal engineering effort.\\n\\nWith just a few lines of code through the Curvy SDK, you can offer your users:\\n\\n- Private receiving via ENS-compatible usernames and stealth addresses\\n- ZK-powered private execution flows  \\n- Shielding and unshielding capabilities  \\n- Compliance-aware privacy infrastructure  \\n\\nThis way, privacy becomes a native feature of your app integrated within your product.\\n\\n## How integration works\\n\\nCurvy provides:\\n\\n- open-source SDK\\n- smart contract infrastructure\\n- multi-chain compatibility\\n- modular privacy components\\n\\n## Partnership program\\n\\nWallets and Web3 products can apply to join the Curvy Partnership Program by contacting:\\n\\n**<hey@curvy.box>**\\n\\n> [!TIP]\\n> As a partner, you can earn a share of protocol fees generated by your users’ private transactions.\\n\\n## Partner benefits\\n\\nIn addition to revenue share, partners receive:\\n\\n- dedicated collaboration channel between our teams\\n- prioritized feature requests\\n- additional chain support (based on demand)\\n- token support expansion\\n- execution flows tailored to partner use cases\\nWe align product development with real ecosystem needs.\\n\\n## Why integrate Curvy?\\n\\n- Non-custodial architecture  \\n- Compliance-aware design  \\n- Enterprise-ready privacy layer  \\n- Revenue-generating integration  \\n- Minimal engineering overhead  \\n","rawMarkdownPath":"/_raw/for-businesses/for-wallets-and-web3-products.md","rawMarkdownTitle":"Curvy for wallets & Web3 product builders","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-businesses/for-wallets-and-web3-products.md"},"headers":[],"relativePath":"for-businesses/for-wallets-and-web3-products.md","filePath":"for-businesses/for-wallets-and-web3-products.md","lastUpdated":1773768298000}'),i={name:"for-businesses/for-wallets-and-web3-products.md"};function o(s,e,l,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="curvy-for-wallets-web3-product-builders" tabindex="-1">Curvy for wallets &amp; Web3 product builders <a class="header-anchor" href="#curvy-for-wallets-web3-product-builders" aria-label="Permalink to &quot;Curvy for wallets &amp; Web3 product builders&quot;">​</a></h1><p>Curvy enables wallets and Web3 applications to integrate privacy flows directly into their product with <strong>zero upfront cost</strong> and minimal engineering effort.</p><p>With just a few lines of code through the Curvy SDK, you can offer your users:</p><ul><li>Private receiving via ENS-compatible usernames and stealth addresses</li><li>ZK-powered private execution flows</li><li>Shielding and unshielding capabilities</li><li>Compliance-aware privacy infrastructure</li></ul><p>This way, privacy becomes a native feature of your app integrated within your product.</p><h2 id="how-integration-works" tabindex="-1">How integration works <a class="header-anchor" href="#how-integration-works" aria-label="Permalink to &quot;How integration works&quot;">​</a></h2><p>Curvy provides:</p><ul><li>open-source SDK</li><li>smart contract infrastructure</li><li>multi-chain compatibility</li><li>modular privacy components</li></ul><h2 id="partnership-program" tabindex="-1">Partnership program <a class="header-anchor" href="#partnership-program" aria-label="Permalink to &quot;Partnership program&quot;">​</a></h2><p>Wallets and Web3 products can apply to join the Curvy Partnership Program by contacting:</p><p><strong><a href="mailto:hey@curvy.box" target="_blank" rel="noreferrer">hey@curvy.box</a></strong></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>As a partner, you can earn a share of protocol fees generated by your users’ private transactions.</p></div><h2 id="partner-benefits" tabindex="-1">Partner benefits <a class="header-anchor" href="#partner-benefits" aria-label="Permalink to &quot;Partner benefits&quot;">​</a></h2><p>In addition to revenue share, partners receive:</p><ul><li>dedicated collaboration channel between our teams</li><li>prioritized feature requests</li><li>additional chain support (based on demand)</li><li>token support expansion</li><li>execution flows tailored to partner use cases We align product development with real ecosystem needs.</li></ul><h2 id="why-integrate-curvy" tabindex="-1">Why integrate Curvy? <a class="header-anchor" href="#why-integrate-curvy" aria-label="Permalink to &quot;Why integrate Curvy?&quot;">​</a></h2><ul><li>Non-custodial architecture</li><li>Compliance-aware design</li><li>Enterprise-ready privacy layer</li><li>Revenue-generating integration</li><li>Minimal engineering overhead</li></ul>',17)])])}const b=r(i,[["render",o]]);export{h as __pageData,b as default};
